function polygonFeature(
  agencySlug: string,
  sourceUrl: string,
  sourceLabel: string,
  coordinates: [number, number][],
  areaName?: string,
): GeoJSON.Feature<GeoJSON.Polygon> {
  return {
    type: 'Feature',
    properties: { agencySlug, serviceType: 'on-demand', sourceUrl, sourceLabel, ...(areaName ? { areaName } : {}) },
    geometry: { type: 'Polygon', coordinates: [coordinates] },
  };
}

